// Porta de entrada da exclusão pedida pelo dashboard.
//
// O repositório é público e a URL deste webhook está no dashboard/index.html,
// à vista de qualquer um. Quem autoriza é o token: ele existe no ambiente do
// n8n e no navegador de quem usa, nunca em arquivo versionado.

const req = $input.first().json;
const cabecalhos = req.headers || {};
const corpo = req.body || {};

const enviado = String(cabecalhos['x-dashboard-token'] || '').trim();
const esperado = String($env.DASHBOARD_TOKEN || '').trim();

// Servidor sem token configurado não apaga nada. O contrário — aceitar tudo
// enquanto falta configuração — transformaria um esquecimento em porta aberta.
const autorizado = esperado.length >= 16 && enviado === esperado;

// Teto de 50 por pedido: engano na tela não vira estrago em massa.
const chaves = (Array.isArray(corpo.chaves) ? corpo.chaves : [])
  .slice(0, 50)
  .map((c) => ({
    update_id: String(c.update_id ?? '').trim(),
    criado_em: String(c.criado_em ?? '').trim(),
    valor: String(c.valor ?? '').trim(),
    descricao: String(c.descricao ?? '').trim(),
  }))
  .filter((c) => c.update_id && c.criado_em);

const motivo = autorizado
  ? ''
  : (esperado ? 'token invalido' : 'DASHBOARD_TOKEN nao configurado no n8n');

return [{ json: { autorizado, motivo, chaves, pedidas: chaves.length } }];

// Onde a exclusão fica segura: o dashboard diz QUAIS lançamentos, nunca em que
// linha eles estão.
//
// O CSV que a página leu tem minutos de atraso e o bot pode ter gravado mais
// linhas nesse intervalo — apagar pela posição que a tela viu apagaria outra
// coisa. Aqui cada chave é casada contra a planilha lida agora, e valor e
// descrição ainda são conferidos antes de qualquer exclusão.

const pedido = $('Conferir pedido').first().json;
const linhas = $input.all().map((i) => i.json);

const norm = (v) => String(v ?? '').trim();
const centavos = (v) => {
  const bruto = String(v ?? '').replace(/[R$\s]/g, '');
  // "1.234,56" e "1234.56" são o mesmo dinheiro
  const limpo = bruto.includes(',') ? bruto.replace(/\./g, '').replace(',', '.') : bruto;
  const n = Number(limpo);
  return isFinite(n) ? Math.round(n * 100) : NaN;
};

const achadas = [];
const perdidas = [];

for (const chave of pedido.chaves || []) {
  const mesmaOrigem = linhas.filter(
    (l) => norm(l.update_id) === chave.update_id && norm(l.criado_em) === chave.criado_em,
  );
  const casadas = mesmaOrigem.filter(
    (l) => centavos(l.valor) === centavos(chave.valor) && norm(l.descricao) === chave.descricao,
  );
  const linha = casadas.length === 1 ? Number(casadas[0].row_number) : 0;

  if (linha >= 2) {
    achadas.push({ ...chave, row_number: linha });
  } else {
    perdidas.push({
      ...chave,
      motivo: casadas.length > 1 ? 'mais de uma linha idêntica' : 'não encontrada na planilha',
    });
  }
}

// De baixo para cima: apagar a linha 5 antes da 9 faria a 9 virar 8.
achadas.sort((a, b) => b.row_number - a.row_number);

// Um item sempre sai daqui: sem ele o fluxo morreria antes de responder ao
// dashboard, que ficaria esperando até o timeout.
if (!achadas.length) return [{ json: { nada: true, perdidas } }];
return achadas.map((a) => ({ json: { ...a, nada: false, perdidas } }));

// Uma resposta só para o dashboard, valha o pedido ter sido negado, ter vindo
// vazio ou ter apagado linhas. Os três caminhos chegam neste nó, então cada
// leitura de nó anterior é protegida: no ramo negado, "Casar linhas" nem rodou.

const ler = (nome, padrao) => {
  try { return $(nome).first().json; } catch (e) { return padrao; }
};

const pedido = ler('Conferir pedido', { autorizado: false, motivo: 'pedido não chegou', pedidas: 0 });

if (!pedido.autorizado) {
  return [{ json: { ok: false, status: 401, motivo: pedido.motivo || 'não autorizado', apagados: 0 } }];
}

let casadas = [];
try {
  casadas = $('Casar linhas').all().map((i) => i.json).filter((c) => !c.nada);
} catch (e) { /* ninguém casou: segue com zero */ }

const perdidas = (ler('Casar linhas', {}).perdidas) || [];

return [{ json: {
  ok: true,
  status: 200,
  pedidos: pedido.pedidas || 0,
  apagados: casadas.length,
  // o dashboard usa esta lista para tirar as linhas da tela na hora: o CSV
  // publicado só vai refletir a exclusão alguns minutos depois
  apagadas: casadas.map((c) => ({ update_id: c.update_id, criado_em: c.criado_em })),
  nao_encontrados: perdidas,
} }];
